mapper.insert:
INSERT INTO magnet_v2_task_event (user_id, task_id, sequence, event_type, payload_json)
SELECT #{userId}, #{taskId}, COALESCE(MAX(sequence) + 1, 0), #{eventType}, #{payloadJson}
FROM magnet_v2_task_event
WHERE task_id = #{taskId}

mapper.select:
SELECT id, user_id, task_id, sequence, event_type, payload_json, created_at
FROM magnet_v2_task_event
WHERE task_id = #{taskId}
ORDER BY sequence DESC
LIMIT #{limit}
